public sealed class Coefficients
{
    // --- 市場（§9-A）---
    public double PriceAdjustSpeed = 0.13;   // 価格の積分項：在庫ギャップ駆動（§9-A 仕組み1）。0.08→0.13＝価格の変動をより顕著に（ユーザー要望）
    public double FlowAdjustSpeed = 0.48;    // 価格の比例項：需給差駆動＝振動の減衰（設計判断A）。需給差を**自然有界な (D−S)/(D+S)∈[−1,1]** で測る（旧 (D−S)/S は S→0 で∞＝FlowCap で蓋が必要だった）。平常域は (D−S)/(D+S)≈x/2 なので旧0.24の2倍=0.48でゲインを温存し、崩壊時は±1で連続有界（蓋不要）
    public double PriceElasticity = 0.5;     // 段B：日次価格探索の需給の価格弾力性。実効需要 eD=D×(rp/P)^ε・実効供給 eS=S×(P/rp)^ε ＝価格が参照から離れると需要減・供給増で**押し戻す復元力**。均衡 P*=rp×(D/S)^(1/2ε) は有限＝クランプが張り付かず外側の安全網へ降格。P=rp(平衡)では eD=D,eS=S＝段Aと同一なので平常較正への影響は小。0=段A（弾力性なし）
    // 加速度的な価格是正（要望）：平衡(100%)近くは緩やか、端ほど急峻。倍率＝Center＋(Edge−Center)×ndist^Power。
    // ndist＝|ln(価格/参照価格)|÷ln(1/床係数)＝床5%・天井2000%で1.0（対称）。50%/150%は今までと同等以下、5%/2000%は直ちに是正。
    public double PriceAmpLnScale = 2.9957;  // amp曲線の端の対数距離（=ln20）。旧は床係数に連動していたが、安全網クランプ幅とは別概念なので分離（クランプを広げてもamp曲線＝是正の強さは不変）。既定はln(20)で従来同値
    public double PriceAmpCenter = 0.7;      // 100%付近の調整倍率（<1＝張り付かない範囲は今までより静か）
    public double PriceAmpEdge = 8.0;        // 床5%/天井2000%での調整倍率（≫1＝極端な乖離は直ちに是正）
    public double PriceAmpPower = 3.0;       // 増幅の凸度（高いほど中間は平坦・端だけ急峻＝加速度的）
    public double SupplyAdjustSpeed = 0.15;  // 供給能力調整の速さ（§9-A 仕組み4）。0.12→0.15＝供給が価格に速く追従しコブウェブ振動を減らす（価格二極化の緩和）。0.18は工業最先進の英を強くしすぎ常勝化したため0.15に抑制
